pub async fn run_agent(task: &str, llm: &dyn LlmClient, tools: &ToolRegistry) -> Result<String, AgentError> {
    let mut messages = vec![Message::system(SYSTEM_PROMPT), Message::user(task)];
    loop { //!issue:1
        let reply = llm.chat(&messages, tools.schemas()).await?;
        messages.push(reply.message.clone());
        if reply.tool_calls.is_empty() {
            return Ok(reply.message.content);
        }
        for call in &reply.tool_calls {
            let result = match tools.invoke(&call.name, &call.args).await {
                Ok(out) => out,
                Err(e) => format!("error: {e}"),
            };
            messages.push(Message::tool(&call.id, result));
        }
    }
}

