export async function callAndAct(prompt: string, customer: Customer): Promise<ActionResult> {
  logger.info("llm request", { prompt, customer }); //!issue:3
  for (let attempt = 1; attempt <= 3; attempt++) { //!issue:2
    try {
      const res = await fetch(MODEL_URL, { //!issue:1
        method: "POST",
        headers: { authorization: `Bearer ${apiKey}`, "content-type": "application/json" },
        body: JSON.stringify({ model: MODEL, input: prompt }),
      });
      const body = await res.json();
      const action = JSON.parse(body.output_text); //!issue:4
      const result = await tools[action.tool](action.args); //!issue:2,4
      return { action: action.tool, result };
    } catch (err) {
      logger.warn("llm call failed, retrying", { attempt, err });
      await sleep(250 * 2 ** attempt);
    }
  }
  throw new Error("llm call failed after 3 attempts");
}

