func CallAndAct(ctx context.Context, prompt string, customer Customer) (*ActionResult, error) {
	log.Info("llm request", "prompt", prompt, "customer", customer) //!issue:3
	client := &http.Client{} //!issue:1
	var lastErr error
	for attempt := 1; attempt <= 3; attempt++ { //!issue:2
		payload, _ := json.Marshal(map[string]string{"model": model, "input": prompt})
		req, _ := http.NewRequest("POST", modelURL, bytes.NewReader(payload)) //!issue:1
		req.Header.Set("Authorization", "Bearer "+apiKey)
		resp, err := client.Do(req)
		if err == nil {
			var body struct {
				OutputText string `json:"output_text"`
			}
			err = json.NewDecoder(resp.Body).Decode(&body)
			resp.Body.Close()
			var action struct {
				Tool string          `json:"tool"`
				Args json.RawMessage `json:"args"`
			}
			if err == nil {
				err = json.Unmarshal([]byte(body.OutputText), &action) //!issue:4
			}
			if err == nil {
				result, terr := tools[action.Tool](ctx, action.Args) //!issue:2,4
				if terr == nil {
					return &ActionResult{Action: action.Tool, Result: result}, nil
				}
				err = terr
			}
		}
		lastErr = err
		log.Warn("llm call failed, retrying", "attempt", attempt, "err", err)
		time.Sleep(time.Duration(250<<attempt) * time.Millisecond)
	}
	return nil, fmt.Errorf("llm call failed after 3 attempts: %w", lastErr)
}

