public ActionResult callAndAct(String prompt, Customer customer) throws Exception {
    log.info("llm request prompt={} customer={}", prompt, customer); //!issue:3
    Exception last = null;
    for (int attempt = 1; attempt <= 3; attempt++) { //!issue:2
        try {
            HttpRequest req = HttpRequest.newBuilder(URI.create(MODEL_URL)) //!issue:1
